async function loadCourses() {
  const r = await fetch('/api/courses');
  if (!r.ok) throw new Error(`HTTP ${r.status}`);
  const data = await r.json();
  if (!Array.isArray(data)) throw new TypeError('Expected array');
  return data;
}
